#!/bin/sh
scan_npu() { NPU_ECOSYSTEM=unknown; NPU_SOC=unknown; NPU_HW=false; NPU_DRIVER=false; NPU_RUNTIME=false; NPU_ACCESS=false; NPU_DEVICE=; _soc="$(read_one /sys/firmware/devicetree/base/compatible) $(read_one /proc/device-tree/compatible) $(read_one /sys/firmware/devicetree/base/model)"; case $_soc in *rk3588*|*RK3588*) NPU_SOC=rk3588; NPU_ECOSYSTEM=rockchip_rknn; NPU_HW=true;; *rockchip*|*Rockchip*) NPU_ECOSYSTEM=rockchip_rknn;; *hailo*) NPU_ECOSYSTEM=hailo;; *edgetpu*) NPU_ECOSYSTEM=coral_edgetpu;; esac; for _n in /dev/dri/renderD* /dev/rknpu* /dev/mpp_service; do _p=$(path "$_n"); [ -e "$_p" ] || continue; NPU_DEVICE=${NPU_DEVICE}${_n}' '; if [ -r "$_p" ] && [ -w "$_p" ]; then NPU_ACCESS=true; fi; done; [ -d "$(path /sys/module/rknpu)" ] && NPU_DRIVER=true; if has_cmd ldconfig; then ldconfig -p 2>/dev/null | grep -q 'librknnrt' && NPU_RUNTIME=true; fi; }
npu_json() { printf '{"ecosystem":'; json_quote "$NPU_ECOSYSTEM"; printf ',"soc":'; json_quote "$NPU_SOC"; printf ',"hardware_detected":%s,"driver_detected":%s,"runtime_detected":%s,"device_accessible":%s,"device_nodes":' "$NPU_HW" "$NPU_DRIVER" "$NPU_RUNTIME" "$NPU_ACCESS"; json_quote "$NPU_DEVICE"; printf ',"inference_verified":false,"status":"%s"}' "$( [ "$NPU_HW" = true ] && echo detected || echo unknown )"; }
